public class Main {
    // Entity：与数据库表一一对应，含敏感字段
    static class UserEntity {
        long id; String name; String phone; String password;
        UserEntity(long id, String name, String phone, String password) {
            this.id = id; this.name = name; this.phone = phone; this.password = password;
        }
    }
    // DTO：入参，只含可写字段
    static class UserCreateDTO {
        String name; String phone; String password;
        UserCreateDTO(String name, String phone, String password) {
            this.name = name; this.phone = phone; this.password = password;
        }
    }
    // VO：出参，脱敏，不含 password
    static class UserVO {
        long id; String name; String phoneMasked;
        UserVO(long id, String name, String phoneMasked) {
            this.id = id; this.name = name; this.phoneMasked = phoneMasked;
        }
    }

    static UserEntity toEntity(UserCreateDTO d) {
        return new UserEntity(0L, d.name, d.phone, d.password);
    }
    static String mask(String phone) {
        if (phone == null || phone.length() < 7) return phone;
        return phone.substring(0, 3) + "****" + phone.substring(phone.length() - 4);
    }
    static UserVO toVO(UserEntity e) {
        return new UserVO(e.id, e.name, mask(e.phone));
    }

    public static void main(String[] args) {
        UserCreateDTO dto = new UserCreateDTO("Tom", "13800001234", "s3cr3t");
        UserEntity saved = toEntity(dto);
        saved.id = 1001L;              // 模拟主键回填
        UserVO vo = toVO(saved);
        System.out.println("entity from DTO: id=" + saved.id + " name=" + saved.name
                + " phone=" + saved.phone);
        System.out.println("VO: id=" + vo.id + " name=" + vo.name
                + " phoneMasked=" + vo.phoneMasked);
        System.out.println("VO carries password field: " + hasPasswordField(vo));
    }

    static boolean hasPasswordField(Object o) {
        for (java.lang.reflect.Field f : o.getClass().getDeclaredFields())
            if (f.getName().toLowerCase().contains("password")) return true;
        return false;
    }
}
